CREATE TABLE `notification_preferences` (`user_id` text PRIMARY KEY NOT NULL REFERENCES `user`(`id`) ON DELETE CASCADE, `daily_reminder` integer DEFAULT true NOT NULL, `invoice_reminders` integer DEFAULT true NOT NULL, `overdue_reminders` integer DEFAULT true NOT NULL, `payment_confirmations` integer DEFAULT true NOT NULL, `budget_alerts` integer DEFAULT true NOT NULL, `weekly_reports` integer DEFAULT false NOT NULL, `marketing_updates` integer DEFAULT true NOT NULL, `timezone` text DEFAULT 'UTC' NOT NULL, `updated_at` integer NOT NULL);
CREATE TABLE `push_devices` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL REFERENCES `user`(`id`) ON DELETE CASCADE, `token` text NOT NULL UNIQUE, `platform` text NOT NULL, `device_id` text NOT NULL, `active` integer DEFAULT true NOT NULL, `permission_status` text NOT NULL, `last_seen_at` integer NOT NULL, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE UNIQUE INDEX `push_device_user_device_idx` ON `push_devices` (`user_id`,`device_id`);
CREATE INDEX `push_device_user_active_idx` ON `push_devices` (`user_id`,`active`);
CREATE TABLE `notification_templates` (`key` text PRIMARY KEY NOT NULL, `name` text NOT NULL, `category` text NOT NULL, `title` text NOT NULL, `body` text NOT NULL, `route` text NOT NULL, `enabled` integer DEFAULT true NOT NULL, `android_enabled` integer DEFAULT true NOT NULL, `web_enabled` integer DEFAULT true NOT NULL, `web_access_mentions` integer DEFAULT false NOT NULL, `updated_at` integer NOT NULL, `updated_by` text NOT NULL);
CREATE TABLE `notification_settings` (`key` text PRIMARY KEY NOT NULL, `global_enabled` integer DEFAULT false NOT NULL, `lifecycle_enabled` integer DEFAULT true NOT NULL, `reminders_enabled` integer DEFAULT true NOT NULL, `transactional_enabled` integer DEFAULT true NOT NULL, `marketing_enabled` integer DEFAULT true NOT NULL, `android_offer_campaigns_enabled` integer DEFAULT false NOT NULL, `quiet_hours_start` integer DEFAULT 21 NOT NULL, `quiet_hours_end` integer DEFAULT 8 NOT NULL, `combined_daily_cap` integer DEFAULT 8 NOT NULL, `transactional_daily_cap` integer DEFAULT 6 NOT NULL, `updated_at` integer NOT NULL, `updated_by` text NOT NULL);
CREATE TABLE `notification_jobs` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL REFERENCES `user`(`id`) ON DELETE CASCADE, `template_key` text NOT NULL, `category` text NOT NULL, `route` text NOT NULL, `title` text NOT NULL, `body` text NOT NULL, `scheduled_for` integer NOT NULL, `expires_at` integer NOT NULL, `status` text NOT NULL, `priority` integer NOT NULL, `dedupe_key` text NOT NULL UNIQUE, `attempts` integer DEFAULT 0 NOT NULL, `last_error` text, `created_at` integer NOT NULL, `updated_at` integer NOT NULL);
CREATE INDEX `notification_job_status_due_idx` ON `notification_jobs` (`status`,`scheduled_for`);
CREATE INDEX `notification_job_user_created_idx` ON `notification_jobs` (`user_id`,`created_at`);
CREATE TABLE `notification_attempts` (`id` text PRIMARY KEY NOT NULL, `job_id` text NOT NULL REFERENCES `notification_jobs`(`id`) ON DELETE CASCADE, `user_id` text NOT NULL, `device_id` text, `status` text NOT NULL, `provider_message_id` text, `error_code` text, `error_message` text, `created_at` integer NOT NULL);
CREATE INDEX `notification_attempt_job_idx` ON `notification_attempts` (`job_id`);
CREATE INDEX `notification_attempt_user_created_idx` ON `notification_attempts` (`user_id`,`created_at`);
CREATE TABLE `notification_events` (`id` text PRIMARY KEY NOT NULL, `user_id` text NOT NULL, `job_id` text, `kind` text NOT NULL, `created_at` integer NOT NULL);
CREATE INDEX `notification_event_user_created_idx` ON `notification_events` (`user_id`,`created_at`);
